from reportlab.platypus import BaseDocTemplate, Frame, Image, PageBreak, PageTemplate, Paragraph, Spacer, Table, TableStyle

RAIZ = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(RAIZ))
from esquema import MAPEO_COLUMNAS, MAPEO_TABLAS

SALIDA = RAIZ / "informe"
R = json.loads((SALIDA / "resultados_verificados.json").read_text(encoding="utf-8"))
O = json.loads((SALIDA / "evidencia_reconciliacion.json").read_text(encoding="utf-8"))
E = json.loads((RAIZ / "pipeline" / "evidencia_idempotencia.json").read_text(encoding="utf-8"))
FECHA = E["fecha"][:10]
AZUL = colors.HexColor("#183B5B")
CLARO = colors.HexColor("#EAF3F8")
GRIS = colors.HexColor("#57636B")
LINEA = colors.HexColor("#BBCAD4")
ESTILOS = getSampleStyleSheet()
ESTILOS.add(ParagraphStyle(name="TituloTP", fontName="Helvetica-Bold", fontSize=17, leading=21, textColor=AZUL, spaceAfter=10))
ESTILOS.add(ParagraphStyle(name="SubTP", fontName="Helvetica-Bold", fontSize=11.3, leading=15, textColor=AZUL, spaceBefore=9, spaceAfter=5))
ESTILOS.add(ParagraphStyle(name="TextoTP", fontName="Helvetica", fontSize=9.4, leading=13.3, spaceAfter=6))
ESTILOS.add(ParagraphStyle(name="PequenoTP", fontName="Helvetica", fontSize=8.1, leading=10.6, spaceAfter=3))
ESTILOS.add(ParagraphStyle(name="CabTP", fontName="Helvetica-Bold", fontSize=8.2, leading=11, textColor=colors.white))
ESTILOS.add(ParagraphStyle(name="NotaTP", fontName="Helvetica-Bold", fontSize=9.3, leading=13, textColor=AZUL, backColor=CLARO, borderColor=LINEA, borderWidth=.4, borderPadding=7, spaceBefore=12, spaceAfter=12))


def p(texto, estilo="TextoTP"):
    return Paragraph(str(texto), ESTILOS[estilo])


def h(texto):
    return p(texto, "SubTP")


def b(texto):
    return p("- " + texto)


def tabla(cabeceras, filas, anchos):
    datos = [[p(x, "CabTP") for x in cabeceras]] + [[p(x, "PequenoTP") for x in fila] for fila in filas]
    t = Table(datos, colWidths=[a * cm for a in anchos], repeatRows=1)
    t.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), AZUL), ("ROWBACKGROUNDS", (0, 1), (-1, -1), [colors.white, CLARO]), ("GRID", (0, 0), (-1, -1), .3, LINEA), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("TOPPADDING", (0, 0), (-1, -1), 5), ("BOTTOMPADDING", (0, 0), (-1, -1), 5), ("LEFTPADDING", (0, 0), (-1, -1), 6), ("RIGHTPADDING", (0, 0), (-1, -1), 6)]))
    return t


def documento(nombre, contenido, etiqueta):
    def pie(canvas, doc):
        canvas.saveState()
        canvas.setStrokeColor(LINEA)
        canvas.line(doc.leftMargin, 1.25 * cm, A4[0] - doc.rightMargin, 1.25 * cm)
        canvas.setFont("Helvetica", 7.3)
        canvas.setFillColor(GRIS)
        canvas.drawString(doc.leftMargin, .85 * cm, f"TP2 - Equipo 1 | {etiqueta} | Corrección {FECHA}")
        canvas.drawRightString(A4[0] - doc.rightMargin, .85 * cm, f"Página {doc.page}")
        canvas.restoreState()
    destino = SALIDA / nombre
    doc = BaseDocTemplate(str(destino), pagesize=A4, leftMargin=1.65*cm, rightMargin=1.65*cm, topMargin=1.5*cm, bottomMargin=1.65*cm)
    doc.addPageTemplates([PageTemplate(id="tp", frames=[Frame(doc.leftMargin, doc.bottomMargin, doc.width, doc.height)], onPage=pie)])
    doc.build(contenido)
    print(destino)


def grafico(nombre, ancho=13.8, alto=7.8):
    return Image(str(RAIZ / "graficos" / nombre), width=ancho*cm, height=alto*cm, kind="proportional")


def dinero(valor):
    return f"${valor:,.2f}".replace(",", "@").replace(".", ",").replace("@", ".")


def informe():
    s = [p("Actividad 5 - Informe de conclusiones", "TituloTP"), p("Segmentación RFM | Iván Vida, Jorge Mindolacion y Brian Bruno", "PequenoTP"), h("1. Pregunta de negocio y enfoque elegido"), p("¿Qué clientes muestran actividad reciente, frecuente y de mayor valor, y cómo priorizar acciones para evaluar? RFM combina recencia, frecuencia y monto porque cada dimensión describe un aspecto distinto del comportamiento histórico. Los puntajes relativos ordenan clientes; no predicen abandono ni representan rentabilidad."), h("2. Decisiones de diseño"), p("Sakila se migró en TP1 a SQL Server y se tradujeron tablas y columnas al español. esquema.py concentra sus equivalencias canónicas. Las plantillas SQL usan tokens; cambiar los nombres físicos del origen en el mapeo adapta las consultas sin repartir esos nombres por el análisis."), p("SQL Server agrega alquileres y pagos y entrega una fila por cliente. Recencia se mide contra la fecha máxima del dataset; frecuencia cuenta alquileres distintos y monto suma pagos vinculados a esos alquileres. El pipeline fue alineado con esa misma definición. Python verifica, perfila, puntúa, grafica y combina el CSV externo."), p(f"Se reconstruyó RFM en pandas desde detalle crudo y coincidió para {R['clientes']} clientes. En esta ejecución SQL tardó {R['sql_segundos']:.3f} s y pandas {R['pandas_segundos']:.3f} s, incluyendo extracción. Son mediciones puntuales; no un estudio de rendimiento."), p("Los quintiles se calculan con qcut sobre rangos; se invierte recencia y los empates se desempatan por identificador. Con 599 clientes, qcut y NTILE difieren en dos fronteras por métrica (99,7 % de coincidencia); la réplica de la distribución NTILE en pandas coincide al 100 %. El desempate es reproducible, pero arbitrario."), p("La conexión usa SQLAlchemy y pyodbc con ODBC Driver 18 y autenticación integrada de Windows. Servidor, base y controlador se configuran por variables de entorno. El proyecto se ejecuta en venv_tp2; no se guardan contraseñas."), p("El CSV ficticio contiene 30 perfiles, canales y descuentos sugeridos. Un left merge one_to_one conserva 599 clientes, con 569 sin perfil externo. Se completan esos atributos con etiquetas informativas y descuento cero. El CSV no cambia los montos históricos ni define los puntajes."), p("La carga reemplaza dbo.TP2_SegmentacionRFM dentro de una transacción. Si falla, se revierte y se propaga el error. fecha_proceso registra la corrida y se excluye al comparar igualdad del contenido de negocio.")]
    s += [PageBreak(), p("3. Diagnóstico de calidad e impacto", "TituloTP"), p(f"El conjunto de trabajo contiene {R['clientes']} clientes y 9 columnas, con {R['nulos']} nulos y {R['duplicados']} duplicados por clave. Se revisaron tipos, percentiles, IQR y controles en SQL y pandas."), tabla(["Control", "Resultado y decisión"], [["Atípicos de monto", f"{R['atipicos']} clientes; límites IQR {dinero(R['limite_inferior'])} y {dinero(R['limite_superior'])}. Se conservan: montos plausibles con alta frecuencia."], ["Pagos sin alquiler, sin pago y negativos", "Cero en los controles de la base revisada; coinciden SQL Server y pandas."], ["Devolución anterior al alquiler", str(R['reglas']['return_before_rental']) + " violaciones; comparación de fechas en SQL y pandas."], ["Pago anterior al alquiler", str(R['reglas']['payment_before_rental']) + " violaciones; se compara con el alquiler asociado."], ["Recencia", f"Mediana {R['mediana_recencia']:.0f} días y {R['recencia_cero']} clientes con cero días. La concentración exige prudencia con los quintiles."]], [5.2, 11.4]), h("Reconciliación corregida"), p("Se eliminaron los conteos de origen escritos a mano. El lector cuenta las tuplas INSERT del archivo de carga indicado por el equipo, sin ejecutar sus instrucciones. Las 16 tablas coinciden con la base actual."), p(f"El archivo contiene {O['pagos']['filas']:,} pagos y el identificador máximo es {O['pagos']['max_id']:,}. Los huecos son {', '.join(map(str, O['pagos']['huecos_id']))}. Confundir MAX(id) con COUNT(*) produjo la falsa diferencia de cinco pagos. Se retira la explicación de pérdidas durante la migración."), p("Procedencia: sql/origen/sakila_carga_sql_server.sql es una copia exacta del script traducido a SQL Server usado en TP1, no un volcado MySQL independiente. film_text no tiene INSERT directo: se deriva de film por un trigger AFTER INSERT acreditado en el DDL adjunto. Se distingue ese conteo derivado de los otros quince."), p("Archivo y DDL tienen huellas SHA-256 completas en evidencia_reconciliacion.json. Ese documento guarda métodos, conteos y comparación SQL. El contraste verifica cantidades, no identidad de todos los valores del origen."), p("Impacto: el RFM sigue calculándose sobre 599 clientes y conserva los 6 atípicos. La corrección elimina una supuesta pérdida de datos que no existía; no reconstruye pagos ni altera las tablas de origen.", "NotaTP")]
    tickets = list(R['ticket_por_quintil'].values())
    s += [PageBreak(), p("4. Hallazgos y decisiones a evaluar", "TituloTP"), h("Hallazgo 1 - El ticket medio cambia poco entre quintiles"), p(f"El promedio por cliente de monto / alquileres va de {dinero(min(tickets))} a {dinero(max(tickets))}: {R['variacion_ticket_pct']:.1f} % entre extremos. La frecuencia alta no se traduce en un ticket claramente superior en esta base. Es un indicador distinto del monto acumulado; no es una media ponderada por alquiler."), grafico("ticket_por_frecuencia_narrativo.png", 13.2, 6.6), p("Decisión propuesta: probar recordatorios de una nueva visita en F=1 y F=2, sin descuento automático, y comparar nuevos alquileres con un grupo de control. Antes de elegir incentivos se necesitan costos y preferencias."), h("Hallazgo 2 - La recencia separa poco el monto"), p("El mapa de calor varía sobre todo por frecuencia. Con F=1 los promedios van aproximadamente de $83,4 a $85,1; con F=5, de $139,3 a $147,0. La distribución de recencia se concentra en cero y alrededor de 175 días."), grafico("heatmap_rfm_monto.png", 13.2, 7.0), p("Decisión propuesta: no seleccionar reactivación solo por el puntaje R. Revisar recencia absoluta e historial, y validar candidatos antes del contacto. Es una lectura descriptiva del gráfico, no una prueba de independencia estadística.")]
