    s = [p("Diagnóstico de calidad de datos", "TituloTP"), h("1. Alcance y estructura"), p(f"Se perfiló el RFM de {R['clientes']} clientes y 9 columnas: tipos, nulos, duplicados, percentiles 1-99, IQR y controles de variante. Hay {R['nulos']} nulos y {R['duplicados']} clientes duplicados. No se imputa ni elimina ninguna fila del conjunto actual."), h("2. Estadísticos y atípicos"), tabla(["Dato", "Recencia", "Frecuencia", "Monto"], [["Mínimo", "0 días", "12", "$50,85"], ["Mediana", "175 días", "26", "$110,73"], ["Promedio", "129,24 días", "26,78", dinero(R['promedio_monto'])], ["Máximo", "181 días", "46", "$221,55"]], [4.3, 4.1, 4.1, 4.1]), p(f"Monto: Q1={dinero(R['q1'])}; Q3={dinero(R['q3'])}; límites IQR {dinero(R['limite_inferior'])}-{dinero(R['limite_superior'])}. Se identifican {R['atipicos']} atípicos (1 %), de $186,62 a $221,55 y 38-46 alquileres. Se conservan por ser plausibles; no son montos negativos ni duplicados."), h("3. Controles de variante y reglas de negocio"), tabla(["Control", "SQL", "Pandas", "Decisión"], [["Pagos sin alquiler / monto de esos pagos", "0 / $0", "0 / $0", "No se descartan ingresos por esta causa."], ["Clientes sin pago", "0", "0", "Se conservan los 599 clientes."], ["Pagos negativos", str(R['reglas']['negative_payments']), str(R['reglas']['negative_payments']), "Regla adicional de monto."], ["Devolución anterior al alquiler", str(R['reglas']['return_before_rental']), str(R['reglas']['return_before_rental']), "Regla temporal de dominio."], ["Pago anterior al alquiler", str(R['reglas']['payment_before_rental']), str(R['reglas']['payment_before_rental']), "Regla temporal de dominio."]], [7, 1.6, 1.8, 6.2]), p("Las devoluciones nulas significan que no hay devolución registrada: no se inventan fechas. Si una corrida futura detecta fechas imposibles, se señalarán para investigar sin borrar operaciones ni corregir fechas automáticamente."), p("Recencia no negativa es una invariante del cálculo contra la fecha máxima, no una regla de negocio independiente. También se comprueba la correspondencia cliente del pago-cliente del alquiler.")]
